// Appends Texas TDLR ids 51-79 and Infection Control ids 80-100
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const tdT=`"Texas TDLR Laws & Regulations"`, tdTes=`"Leyes y Regulaciones de Texas TDLR"`, tdPt=`"Licensing & Regulation"`, tdPtes=`"Licencias y Regulaciones"`
const icT=`"Infection Control & Sanitation"`, icTes=`"Control de Infecciones y Saneamiento"`, icPt=`"Infection Control"`, icPtes=`"Control de Infecciones"`

const tdQ = [
  { id: 51, question: "Eyelash extension services in Texas require:", question_es: "Los servicios de extensiones de pestañas en Texas requieren:", options: ["A valid Esthetician license or a standalone Eyelash Extension certificate issued by TDLR — individuals without one of these licenses cannot legally apply eyelash extensions", "Only a basic cosmetology license — no esthetics-specific credential is needed for lash extensions", "No license at all — eyelash extensions are classified as cosmetic, not cosmetology, under Texas law", "A physician's supervision letter for every eyelash extension appointment"], options_es: ["Una licencia de Esteticista válida o un certificado independiente de Extensión de Pestañas emitido por TDLR — las personas sin una de estas licencias no pueden aplicar extensiones de pestañas legalmente", "Solo una licencia básica de cosmetología — no se necesita una credencial específica de estética para las extensiones de pestañas", "Ninguna licencia en absoluto — las extensiones de pestañas se clasifican como cosméticas, no de cosmetología, según la ley de Texas", "Una carta de supervisión médica para cada cita de extensión de pestañas"], correct: 0, explanation: "In Texas, eyelash extension services fall under esthetics licensing. Estheticians may perform lash extensions as part of their scope. TDLR also offers a standalone Eyelash Extension certificate for those who want to perform only that service. Performing lash extensions without proper licensure is a TDLR violation." },
  { id: 52, question: "Eyebrow and eyelash tinting services are within the scope of practice for a Texas esthetician because:", question_es: "Los servicios de tintura de cejas y pestañas están dentro del alcance de práctica de un esteticista de Texas porque:", options: ["They are cosmetic coloring procedures applied to facial hair, which fall within the esthetics scope of skin and facial care as defined by Texas law", "They are the same as permanent hair color and require a cosmetology operator license", "TDLR has not addressed tinting — estheticians use professional discretion", "Tinting requires a physician's prescription for the dye product to be used legally"], options_es: ["Son procedimientos de coloración cosmética aplicados al vello facial, que caen dentro del alcance de estética del cuidado de la piel y facial según lo definido por la ley de Texas", "Son iguales al color de cabello permanente y requieren una licencia de operador de cosmetología", "TDLR no ha abordado la tintura — los esteticistas usan discreción profesional", "La tintura requiere una receta médica para que el producto de tinte se use legalmente"], correct: 0, explanation: "Eyebrow and eyelash tinting (semi-permanent color applied to facial brow and lash hair) falls within the esthetics scope of facial services. A patch test is essential before tinting due to the proximity to the eyes and potential for allergic reactions to tinting products." },
  { id: 53, question: "A Texas esthetician who performs services at an unlicensed esthetics establishment:", question_es: "Un esteticista de Texas que realiza servicios en un establecimiento de estética sin licencia:", options: ["Is contributing to a TDLR violation — both the establishment (for operating without a license) and the esthetician (for working there) may face TDLR enforcement action", "Is protected because their individual license remains valid regardless of the establishment's licensing status", "Only the establishment owner is penalized — individual estheticians bear no responsibility for the establishment's compliance", "Must report the unlicensed establishment to TDLR but may continue working there in the interim"], options_es: ["Está contribuyendo a una violación de TDLR — tanto el establecimiento (por operar sin licencia) como el esteticista (por trabajar allí) pueden enfrentar acciones de aplicación de TDLR", "Está protegido porque su licencia individual sigue siendo válida independientemente del estado de licencia del establecimiento", "Solo el propietario del establecimiento es penalizado — los esteticistas individuales no tienen responsabilidad por el cumplimiento del establecimiento", "Debe reportar el establecimiento sin licencia a TDLR pero puede continuar trabajando allí en el ínterin"], correct: 0, explanation: "Performing services at an unlicensed establishment is a violation for both the establishment and the individual esthetician. An esthetician should verify that any establishment where they practice holds a valid TDLR establishment license. Working in an unlicensed establishment risks disciplinary action against the individual's license." },
  { id: 54, question: "Texas TDLR rules require estheticians to maintain adequate personal hygiene during services because:", question_es: "Las reglas de TDLR de Texas requieren que los esteticistas mantengan una higiene personal adecuada durante los servicios porque:", options: ["Direct physical contact with clients creates the potential for transmitting pathogens from the esthetician's body to the client's skin — personal cleanliness is a basic sanitation requirement", "Personal hygiene only affects the esthetician's personal health, not client safety", "Appearance is important for professional image but has no regulatory basis in TDLR rules", "Personal hygiene requirements only apply when performing waxing services, not facials"], options_es: ["El contacto físico directo con los clientes crea el potencial de transmitir patógenos del cuerpo del esteticista a la piel del cliente — la limpieza personal es un requisito básico de saneamiento", "La higiene personal solo afecta la salud personal del esteticista, no la seguridad del cliente", "La apariencia es importante para la imagen profesional pero no tiene base regulatoria en las reglas de TDLR", "Los requisitos de higiene personal solo se aplican cuando se realizan servicios de encerado, no faciales"], correct: 0, explanation: "Personal hygiene (clean hands, clean clothing, no visible skin infections) is fundamental to client safety in esthetics. TDLR sanitation rules require estheticians to maintain personal cleanliness during all client services. Pathogens on the esthetician's skin or clothing can be transmitted to clients during close-contact esthetics work." },
  { id: 55, question: "Proper hand washing in an esthetics establishment requires:", question_es: "El lavado correcto de manos en un establecimiento de estética requiere:", options: ["Washing with soap and warm water for a minimum of 20 seconds before each client service, after removing gloves, after touching contaminated surfaces, and whenever hands may have been soiled", "Using hand sanitizer alone — soap and water are not required by TDLR rules", "Washing only at the beginning of the workday and after lunch breaks", "Only washing hands after services that involve blood contact — routine facials do not require hand washing between clients"], options_es: ["Lavarse con jabón y agua tibia durante un mínimo de 20 segundos antes de cada servicio al cliente, después de quitarse los guantes, después de tocar superficies contaminadas y siempre que las manos puedan estar sucias", "Usar solo desinfectante de manos — el jabón y el agua no son requeridos por las reglas de TDLR", "Lavarse solo al comienzo del día de trabajo y después de los descansos para el almuerzo", "Solo lavarse las manos después de servicios que involucran contacto con sangre — los faciales de rutina no requieren lavado de manos entre clientes"], correct: 0, explanation: "Hand washing with soap and water is required before every client service, after touching potentially contaminated surfaces, after glove removal, and whenever hands are visibly soiled. The mechanical action of washing plus soap are essential — hand sanitizer alone is insufficient when hands are visibly dirty." },
  { id: 56, question: "Texas TDLR rules regarding glove use in esthetics services require:", question_es: "Las reglas de TDLR de Texas sobre el uso de guantes en los servicios de estética requieren:", options: ["Gloves must be worn whenever there is potential contact with blood, body fluids, non-intact skin (open lesions), or mucous membranes — gloves are required for extractions, waxing, and services where skin is broken", "Gloves are only required for chemical peel services — routine facials do not require gloves", "Gloves must be worn during all esthetics services at all times without exception", "Gloves are optional — estheticians use professional judgment about when to wear them"], options_es: ["Los guantes deben usarse siempre que haya potencial contacto con sangre, fluidos corporales, piel no intacta (lesiones abiertas) o membranas mucosas — los guantes son necesarios para extracciones, encerado y servicios donde la piel está rota", "Los guantes solo se requieren para los servicios de peel químico — los faciales de rutina no requieren guantes", "Los guantes deben usarse durante todos los servicios de estética en todo momento sin excepción", "Los guantes son opcionales — los esteticistas usan el juicio profesional sobre cuándo usarlos"], correct: 0, explanation: "Standard precautions require glove use when there is potential exposure to blood, body fluids, or non-intact skin. In esthetics, this includes extractions (which may produce blood), waxing (can remove skin), chemical peels (may disrupt skin barrier), and services on any client with open lesions or active infections." },
  { id: 57, question: "OSHA's relevance to Texas esthetics establishments includes:", question_es: "La relevancia de OSHA para los establecimientos de estética de Texas incluye:", options: ["OSHA standards apply to employee safety in esthetics workplaces — including the Hazard Communication Standard (SDS), Bloodborne Pathogen Standard, and requirements for PPE and safe chemical handling", "OSHA only regulates manufacturing facilities — esthetics establishments are exempt from all OSHA standards", "OSHA exclusively handles workers' compensation claims — it does not set workplace safety standards for esthetics", "OSHA standards only apply when the establishment has 50 or more employees"], options_es: ["Los estándares de OSHA se aplican a la seguridad de los empleados en los lugares de trabajo de estética — incluyendo el Estándar de Comunicación de Peligros (SDS), el Estándar de Patógenos de Transmisión Sanguínea y los requisitos para EPP y manejo seguro de químicos", "OSHA solo regula las instalaciones de fabricación — los establecimientos de estética están exentos de todos los estándares de OSHA", "OSHA maneja exclusivamente las reclamaciones de compensación de trabajadores — no establece estándares de seguridad en el lugar de trabajo para la estética", "Los estándares de OSHA solo se aplican cuando el establecimiento tiene 50 o más empleados"], correct: 0, explanation: "OSHA standards apply to esthetics workplaces with employees, regardless of size. Key applicable standards: Hazard Communication (SDS and chemical labeling), Bloodborne Pathogen Standard (for services with blood exposure potential), and general PPE requirements. Self-employed booth renters may have different OSHA obligations." },
  { id: 58, question: "A Texas esthetics license examination candidate who fails the written exam may:", question_es: "Un candidato al examen de licencia de estética de Texas que reprueba el examen escrito puede:", options: ["Retake the examination after paying the reexamination fee — there is no statutory limit on retake attempts, but each requires registration and payment to PSI", "Only retake the exam once within 30 days at no charge before having to re-enroll in esthetics school", "Retake only the failed portions without restriction — PSI allows unlimited free retakes", "Never retake the exam — they must apply for a provisional license instead"], options_es: ["Volver a tomar el examen después de pagar la tarifa de reexaminación — no hay límite estatutario en los intentos de repetición, pero cada uno requiere registro y pago a PSI", "Solo volver a tomar el examen una vez dentro de los 30 días sin cargo antes de tener que volver a inscribirse en la escuela de estética", "Volver a tomar solo las partes reprobadas sin restricción — PSI permite repeticiones ilimitadas gratuitas", "Nunca volver a tomar el examen — deben solicitar una licencia provisional en su lugar"], correct: 0, explanation: "Candidates who fail the PSI esthetics exam (written or practical) may retake the failed examination after paying the reexamination fee to PSI. There is no statutory limit on the number of retake attempts. Candidates should study the areas where they were deficient before retesting." },
  { id: 59, question: "An esthetics school's curriculum must include which content areas to be TDLR-approved?", question_es: "El plan de estudios de una escuela de estética debe incluir qué áreas de contenido para ser aprobado por TDLR?", options: ["TDLR specifies the required subject areas for the esthetics curriculum — including skin analysis, sanitation, facial treatments, hair removal, makeup, chemical services, and Texas laws and rules — and schools must meet these standards", "Schools can teach any content they choose — TDLR only reviews the total number of hours, not specific subject areas", "Only practical skills are required — written theory content is optional in the esthetics curriculum", "The curriculum is set by national cosmetology organizations, not TDLR"], options_es: ["TDLR especifica las áreas temáticas requeridas para el plan de estudios de estética — incluyendo análisis de piel, saneamiento, tratamientos faciales, depilación, maquillaje, servicios químicos y leyes y reglas de Texas — y las escuelas deben cumplir con estos estándares", "Las escuelas pueden enseñar cualquier contenido que elijan — TDLR solo revisa el número total de horas, no las áreas temáticas específicas", "Solo se requieren habilidades prácticas — el contenido teórico escrito es opcional en el plan de estudios de estética", "El plan de estudios es establecido por organizaciones nacionales de cosmetología, no TDLR"], correct: 0, explanation: "TDLR specifies both the total hours (750) and the subject matter areas that must be covered in the Texas esthetics curriculum. Schools must include all TDLR-required content areas to maintain their school license. Hours in non-required subjects do not substitute for required subject areas." },
  { id: 60, question: "Client chemical service records (such as records of chemical peel applications) should include:", question_es: "Los registros de servicios químicos para clientes (como registros de aplicaciones de peel químico) deben incluir:", options: ["Date of service, products used (including concentration and pH), application time, client's skin reaction, any adverse effects, and follow-up recommendations — this creates a safety record for future services", "Only the brand name of the peel product used and the date", "Nothing — verbal documentation is sufficient for chemical service records in Texas esthetics", "The client's payment method and service price only"], options_es: ["Fecha del servicio, productos usados (incluyendo concentración y pH), tiempo de aplicación, reacción de la piel del cliente, cualquier efecto adverso y recomendaciones de seguimiento — esto crea un registro de seguridad para futuros servicios", "Solo el nombre de la marca del producto peel usado y la fecha", "Nada — la documentación verbal es suficiente para los registros de servicios químicos en la estética de Texas", "Solo el método de pago del cliente y el precio del servicio"], correct: 0, explanation: "Detailed chemical service records are essential for safety. If a client returns with an adverse reaction, complete records allow the esthetician and physician to identify the causative product. Records also protect the esthetician professionally and demonstrate appropriate care during the service." },
  { id: 61, question: "A patch test before applying a chemical or tinting product on a client is important because:", question_es: "Una prueba de parche antes de aplicar un producto químico o de tintura en un cliente es importante porque:", options: ["It identifies clients who are allergic or sensitized to a product ingredient before full application — preventing a potentially severe allergic reaction on the face, eyes, or body", "It is only required by state law — there is no actual clinical benefit to patch testing", "It is only necessary for clients who have had allergic reactions in the past", "A patch test is only performed by physicians — estheticians rely on verbal allergy history instead"], options_es: ["Identifica a los clientes que son alérgicos o sensibilizados a un ingrediente del producto antes de la aplicación completa — previniendo una posible reacción alérgica severa en el rostro, los ojos o el cuerpo", "Solo es requerida por la ley estatal — no hay un beneficio clínico real en las pruebas de parche", "Solo es necesaria para clientes que han tenido reacciones alérgicas en el pasado", "Una prueba de parche solo la realizan los médicos — los esteticistas confían en la historia verbal de alergias en su lugar"], correct: 0, explanation: "A patch test detects sensitization before service. Even if a client has used a product before without reaction, sensitization can develop with subsequent exposure. A test on a small skin area 24–48 hours before service reveals allergic reactions before full application near sensitive areas like the eyes." },
  { id: 62, question: "A Texas esthetician must refuse service when a client presents with:", question_es: "Un esteticista de Texas debe rechazar el servicio cuando un cliente presenta:", options: ["Contraindications in the service area — such as open wounds, contagious skin conditions (impetigo, herpes simplex outbreak, ringworm), severe sunburn, or undiagnosed lesions that appear suspicious", "Dry or dehydrated skin — this is a normal client condition", "Any facial hair — estheticians only perform services on clean-shaven faces", "A history of previous esthetic services at a competing establishment"], options_es: ["Contraindicaciones en el área de servicio — como heridas abiertas, condiciones cutáneas contagiosas (impétigo, brote de herpes simple, tiña), quemaduras de sol severas o lesiones no diagnosticadas que parecen sospechosas", "Piel seca o deshidratada — esta es una condición normal del cliente", "Cualquier vello facial — los esteticistas solo realizan servicios en rostros afeitados", "Un historial de servicios estéticos previos en un establecimiento competidor"], correct: 0, explanation: "Contraindications require service refusal to protect both the client and the esthetician. Performing services on infected, contagious, or compromised skin can worsen the client's condition and expose the esthetician's other clients to pathogens through tools. The esthetician should explain the refusal and recommend the client see a physician." },
  { id: 63, question: "Which of the following advanced modalities may fall within a Texas Master Esthetician's expanded scope?", question_es: "¿Cuál de las siguientes modalidades avanzadas puede estar dentro del alcance ampliado de un Esteticista Maestro de Texas?", options: ["Advanced manual lymphatic drainage techniques, microcurrent facial treatments, body treatments and wraps, and more advanced chemical exfoliation modalities beyond the basic esthetician scope", "Ablative CO2 laser resurfacing and injectable neurotoxins", "Surgical procedures such as brow lifts and eyelid surgery", "Prescribing systemic acne medications and topical retinoids"], options_es: ["Técnicas avanzadas de drenaje linfático manual, tratamientos faciales de microcorriente, tratamientos y envolturas corporales y modalidades de exfoliación química más avanzadas más allá del alcance básico de esteticista", "Resurfacing láser ablativo de CO2 y neurotoxinas inyectables", "Procedimientos quirúrgicos como levantamiento de cejas y cirugía de párpados", "Prescribir medicamentos sistémicos para el acné y retinoides tópicos"], correct: 0, explanation: "The Master Esthetician license in Texas allows a broader scope than the standard Esthetician license. This may include advanced modalities like lymphatic drainage, microcurrent, body treatments, and more advanced chemical services. Surgical, injectable, and prescription services remain outside the scope regardless of license level." },
  { id: 64, question: "Light therapy (LED phototherapy) used in an esthetics establishment is generally considered:", question_es: "La fototerapia de luz (LED) utilizada en un establecimiento de estética es generalmente considerada:", options: ["A non-ablative treatment within the esthetics scope — LED devices used at non-laser, non-ionizing levels for cosmetic purposes (acne reduction, anti-aging) may be used by estheticians within appropriate parameters", "A medical device that requires physician ownership and supervision for all LED treatments", "Prohibited for all estheticians in Texas — only physicians may use any form of light device", "Equivalent to ablative laser treatment — the same restrictions apply to LED and surgical lasers"], options_es: ["Un tratamiento no ablativo dentro del alcance de estética — los dispositivos LED utilizados a niveles no láser y no ionizantes para propósitos cosméticos (reducción del acné, antienvejecimiento) pueden ser usados por esteticistas dentro de los parámetros apropiados", "Un dispositivo médico que requiere propiedad del médico y supervisión para todos los tratamientos con LED", "Prohibido para todos los esteticistas en Texas — solo los médicos pueden usar cualquier forma de dispositivo de luz", "Equivalente al tratamiento láser ablativo — las mismas restricciones se aplican al LED y los láseres quirúrgicos"], correct: 0, explanation: "Non-ablative LED phototherapy (not surgical laser) at cosmetic energy levels is generally considered within the esthetics scope for appropriate devices marketed for cosmetic use. Ablative and high-energy laser treatments remain medical procedures. Estheticians should verify current TDLR guidance for specific devices." },
  { id: 65, question: "Galvanic current used in an esthetics facial service works by:", question_es: "La corriente galvánica utilizada en un servicio facial de estética funciona mediante:", options: ["Using direct current to perform ionization — either driving water-soluble products deeper into the skin (cataphoresis/iontophoresis) or using electrical current to soften sebum plugs and aid extraction (desincrustation)", "Generating heat deep in the dermis to stimulate collagen production through thermal injury", "Ablating the superficial skin layer through electromagnetic pulse energy", "Producing ultrasonic vibration to break up calcium deposits in the skin"], options_es: ["Usar corriente directa para realizar la ionización — ya sea impulsando productos solubles en agua más profundamente en la piel (cataforesis/iontoforesis) o usando corriente eléctrica para suavizar los tapones de sebo y ayudar a la extracción (desincustación)", "Generar calor profundo en la dermis para estimular la producción de colágeno a través de lesiones térmicas", "Ablar la capa superficial de la piel a través de energía de pulso electromagnético", "Producir vibración ultrasónica para descomponer los depósitos de calcio en la piel"], correct: 0, explanation: "Galvanic current (direct current) is used in two ways in esthetics: (1) iontophoresis/cataphoresis — using electrical charge to drive water-soluble products into the skin, and (2) desincrustation — using the current to soften and loosen sebum and debris from follicles for easier extraction." },
  { id: 66, question: "Texas esthetics law prohibits estheticians from performing 'ablative' treatments because:", question_es: "La ley de estética de Texas prohíbe a los esteticistas realizar tratamientos 'ablativos' porque:", options: ["Ablative treatments (such as CO2 laser, erbium laser, deep chemical peels) remove or destroy living tissue, causing wounds that require medical oversight for safe healing — these are surgical/medical procedures beyond the esthetics scope", "Ablative treatments are prohibited only if performed without anesthesia", "TDLR prohibits ablative treatments only for estheticians without Master Esthetician credentials", "Ablative treatments are prohibited solely because of cost — they must be performed in medical offices for billing insurance purposes"], options_es: ["Los tratamientos ablativos (como láser de CO2, láser de erbio, peels químicos profundos) eliminan o destruyen el tejido vivo, causando heridas que requieren supervisión médica para una curación segura — estos son procedimientos quirúrgicos/médicos más allá del alcance de la estética", "Los tratamientos ablativos solo están prohibidos si se realizan sin anestesia", "TDLR prohíbe los tratamientos ablativos solo para esteticistas sin credenciales de Esteticista Maestro", "Los tratamientos ablativos están prohibidos únicamente por razones de costo — deben realizarse en consultorios médicos para facturar a los seguros"], correct: 0, explanation: "Ablative treatments remove or vaporize living tissue, creating true wounds. The healing process requires medical management to prevent infection and scarring. Because these procedures create medical wounds, they are classified as surgical/medical procedures that fall outside the esthetics scope regardless of the device used." },
  { id: 67, question: "A Texas esthetics establishment that offers body waxing services must ensure:", question_es: "Un establecimiento de estética de Texas que ofrece servicios de encerado corporal debe asegurar:", options: ["All estheticians performing waxing hold a valid Texas Esthetician license, use single-application wax applicators (no double-dipping), maintain proper wax temperatures, and follow all sanitation protocols for waxing services", "Body waxing below the neck requires a separate body waxing certificate in addition to the esthetics license", "Waxing is an unlicensed service in Texas — no license is required for waxing services", "Wax pots must be emptied and cleaned only at the end of each business day"], options_es: ["Todos los esteticistas que realizan encerado tienen una licencia de Esteticista de Texas válida, usan aplicadores de cera de aplicación única (sin doble inmersión), mantienen temperaturas de cera adecuadas y siguen todos los protocolos de saneamiento para los servicios de encerado", "El encerado corporal por debajo del cuello requiere un certificado de encerado corporal separado además de la licencia de estética", "El encerado es un servicio sin licencia en Texas — no se requiere licencia para los servicios de encerado", "Los potes de cera solo deben vaciarse y limpiarse al final de cada día de negocios"], correct: 0, explanation: "Waxing is within the Texas Esthetician scope. Critical safety rules include: never double-dip applicators (reusing an applicator in the wax pot after client contact contaminates the entire pot), use appropriate wax temperatures to avoid burns, and follow sanitation protocols. Single-use wax applicators are required between clients." },
  { id: 68, question: "Single-use items in a Texas esthetics establishment:", question_es: "Los artículos de uso único en un establecimiento de estética de Texas:", options: ["Must be used on only one client and then discarded — items such as cotton swabs, gauze, lancets, single-use wax applicators, and disposable towels cannot be cleaned and reused between clients", "May be reused after soaking in disinfectant for 10 minutes", "Are only required for services involving chemical products — routine facial implements may be reused without disinfection", "Are recommended but not required by TDLR sanitation rules"], options_es: ["Deben usarse en un solo cliente y luego desecharse — artículos como hisopos de algodón, gasa, lancetas, aplicadores de cera de uso único y toallas desechables no pueden limpiarse y reutilizarse entre clientes", "Pueden reutilizarse después de sumergirse en desinfectante durante 10 minutos", "Solo se requieren para los servicios que involucran productos químicos — los implementos faciales de rutina pueden reutilizarse sin desinfección", "Son recomendados pero no requeridos por las reglas de saneamiento de TDLR"], correct: 0, explanation: "Single-use (disposable) items are used once and discarded because their porous or soft structure cannot be adequately disinfected. Using a single-use item on more than one client creates a direct pathway for pathogen transmission. Examples: lancets, cotton pads, wax applicators, spatulas used in products." },
  { id: 69, question: "EPA-registered disinfectants used in Texas esthetics establishments must be:", question_es: "Los desinfectantes registrados por la EPA utilizados en los establecimientos de estética de Texas deben ser:", options: ["Used according to the manufacturer's label instructions — including proper dilution, contact time, and conditions of use — to be effective and compliant with TDLR requirements", "Mixed at double the manufacturer's recommended concentration for extra safety", "Applied only to implements, never to work surfaces", "Replaced daily regardless of whether they were used or opened"], options_es: ["Usados según las instrucciones de la etiqueta del fabricante — incluyendo la dilución adecuada, el tiempo de contacto y las condiciones de uso — para ser efectivos y cumplir con los requisitos de TDLR", "Mezclados al doble de la concentración recomendada por el fabricante para mayor seguridad", "Aplicados solo a implementos, nunca a las superficies de trabajo", "Reemplazados diariamente independientemente de si se usaron o abrieron"], correct: 0, explanation: "EPA-registered disinfectants must be used strictly according to their label — the label is the law under federal pesticide regulations. Diluting too much reduces effectiveness; diluting too little can damage implements and cause skin irritation. The required contact (wet) time on the label must be met to achieve disinfection." },
  { id: 70, question: "Under Texas TDLR rules, when may an esthetics establishment use a solution (such as isopropyl alcohol or hydrogen peroxide) as the sole disinfectant for implements?", question_es: "Bajo las reglas de TDLR de Texas, ¿cuándo puede un establecimiento de estética usar una solución (como alcohol isopropílico o peróxido de hidrógeno) como el único desinfectante para implementos?", options: ["Only when the solution has EPA registration as a hospital-level (or higher) disinfectant and is used at the correct concentration and contact time specified on the label — isopropyl alcohol at less than 70% is NOT effective and is insufficient", "Isopropyl alcohol at any concentration is always sufficient for disinfecting esthetics implements under TDLR rules", "Only water-based disinfectant solutions are allowed — alcohol-based products are prohibited in Texas esthetics establishments", "Any household cleaning product may substitute for EPA-registered disinfectants in an emergency"], options_es: ["Solo cuando la solución tiene registro de la EPA como desinfectante de nivel hospitalario (o superior) y se usa a la concentración correcta y el tiempo de contacto especificado en la etiqueta — el alcohol isopropílico a menos del 70% NO es efectivo e insuficiente", "El alcohol isopropílico a cualquier concentración siempre es suficiente para desinfectar los implementos de estética bajo las reglas de TDLR", "Solo se permiten soluciones desinfectantes a base de agua — los productos a base de alcohol están prohibidos en los establecimientos de estética de Texas", "Cualquier producto de limpieza doméstico puede sustituir a los desinfectantes registrados por la EPA en una emergencia"], correct: 0, explanation: "Disinfectants used in Texas esthetics establishments must be EPA-registered and appropriate for the level of disinfection required. Isopropyl alcohol is not a sufficient disinfectant for all esthetics implements — especially for pathogens like mycobacteria. Quaternary ammonium compounds and phenolic disinfectants are more commonly used for implement disinfection." },
  { id: 71, question: "A Texas esthetician's license may be suspended by TDLR (as opposed to permanently revoked) when:", question_es: "La licencia de un esteticista de Texas puede ser suspendida por TDLR (en lugar de revocarse permanentemente) cuando:", options: ["The violation warrants a temporary removal from practice — such as a first major sanitation violation, impairment, or a situation where correction is possible — suspension allows for remediation before the esthetician may return to practice", "Only permanent revocation is available — TDLR has no authority to issue temporary suspensions", "Any client complaint, regardless of merit, results in automatic suspension", "Suspension only occurs when an esthetician fails to pay their renewal fee on time"], options_es: ["La violación justifica una eliminación temporal de la práctica — como una primera violación mayor de saneamiento, deterioro o una situación donde la corrección es posible — la suspensión permite la remediación antes de que el esteticista pueda volver a la práctica", "Solo está disponible la revocación permanente — TDLR no tiene autoridad para emitir suspensiones temporales", "Cualquier queja del cliente, independientemente de su mérito, resulta en suspensión automática", "La suspensión solo ocurre cuando un esteticista no paga su tarifa de renovación a tiempo"], correct: 0, explanation: "TDLR has a range of disciplinary options including probation, suspension (temporary), and revocation (permanent). Suspension may be appropriate for violations where correction and rehabilitation are possible. Revocation is typically reserved for the most serious violations or repeated non-compliance." },
  { id: 72, question: "Texas esthetics law requires that all implements used for skin services be:", question_es: "La ley de estética de Texas requiere que todos los implementos utilizados para los servicios de piel sean:", options: ["Properly cleaned (removal of visible debris) and then disinfected with an EPA-registered disinfectant between each client — non-porous implements may be disinfected; porous implements must be single-use or client-dedicated", "Only rinsed with hot water between clients — soap and disinfectant are not required for facial implements", "Autoclaved (sterilized) between each client — disinfection alone is not sufficient for any esthetics implement", "Replaced with new implements after every 10 clients — single-use is not required for every client"], options_es: ["Correctamente limpiados (eliminación de residuos visibles) y luego desinfectados con un desinfectante registrado por la EPA entre cada cliente — los implementos no porosos pueden desinfectarse; los implementos porosos deben ser de uso único o dedicados al cliente", "Solo enjuagados con agua caliente entre clientes — el jabón y el desinfectante no son requeridos para los implementos faciales", "Esterilizados (con autoclave) entre cada cliente — la desinfección sola no es suficiente para ningún implemento de estética", "Reemplazados con nuevos implementos después de cada 10 clientes — el uso único no es requerido para cada cliente"], correct: 0, explanation: "The required standard for most esthetics implements is disinfection — not sterilization. Clean first (remove debris), then disinfect with EPA-registered product at proper dilution and contact time. Porous implements (files, brushes with natural bristles) cannot be adequately disinfected and must be single-use or dedicated to one client." },
  { id: 73, question: "The Texas TDLR rules about wax pot sanitation require:", question_es: "Las reglas de TDLR de Texas sobre el saneamiento de los potes de cera requieren:", options: ["Never re-dipping used applicators into the wax pot (no double-dipping) — once an applicator touches a client, it is contaminated and must not return to the pot; wax pots must be kept covered when not in use", "Wax pots should be heated to boiling temperature to self-sterilize between clients", "Wax pots may be shared across multiple stations without additional sanitation measures", "Liquid wax must be replaced weekly regardless of use volume"], options_es: ["Nunca volver a sumergir aplicadores usados en el pote de cera (sin doble inmersión) — una vez que un aplicador toca a un cliente, está contaminado y no debe volver al pote; los potes de cera deben mantenerse tapados cuando no están en uso", "Los potes de cera deben calentarse a temperatura de ebullición para auto-esterilizarse entre clientes", "Los potes de cera pueden compartirse entre múltiples estaciones sin medidas de saneamiento adicionales", "La cera líquida debe reemplazarse semanalmente independientemente del volumen de uso"], correct: 0, explanation: "Double-dipping (returning a used applicator to the wax pot) is one of the most common and serious wax service sanitation violations. A used applicator carries client skin cells, bacteria, and fluids — reintroducing it into the pot contaminates all remaining wax, which is then applied to subsequent clients, creating a transmission vector." },
  { id: 74, question: "Under Texas TDLR rules, linens (towels, sheets) used in an esthetics service must:", question_es: "Bajo las reglas de TDLR de Texas, la ropa de cama (toallas, sábanas) utilizada en un servicio de estética debe:", options: ["Be freshly laundered for each client — reusing linens between clients without laundering is a sanitation violation that can transmit skin conditions, bacteria, and parasites between clients", "Be washed daily at the end of the business day — reuse between clients during the same day is acceptable", "Be disinfected by spraying with EPA-registered disinfectant between clients instead of laundering", "Only be changed when visibly soiled — the esthetician may use judgment about linen changes"], options_es: ["Ser lavados frescos para cada cliente — reutilizar la ropa de cama entre clientes sin lavar es una violación de saneamiento que puede transmitir condiciones cutáneas, bacterias y parásitos entre clientes", "Lavarse diariamente al final del día de negocios — la reutilización entre clientes durante el mismo día es aceptable", "Desinfectarse rociando con desinfectante registrado por la EPA entre clientes en lugar de lavarlos", "Solo cambiarse cuando estén visiblemente sucios — el esteticista puede usar el juicio sobre los cambios de ropa de cama"], correct: 0, explanation: "Freshly laundered linens for each client is a fundamental sanitation requirement. Shared or reused linens transmit bacteria, fungi, viruses, and parasites (such as head lice or scabies) between clients. Used linens must be stored in a covered, separate container until laundered." },
  { id: 75, question: "A Texas esthetics establishment must maintain a supply of clean, disinfected implements in:", question_es: "Un establecimiento de estética de Texas debe mantener un suministro de implementos limpios y desinfectados en:", options: ["A clean, covered container or storage area that is separate from dirty/used implements — clean and dirty implements must never be stored together to prevent cross-contamination", "The same container as used implements — as long as they are rinsed first", "An open tray on the service cart where air can circulate to keep them sanitary", "The disinfectant solution at all times — implements should remain submerged until use"], options_es: ["Un recipiente o área de almacenamiento limpia y cubierta que esté separada de los implementos sucios/usados — los implementos limpios y sucios nunca deben almacenarse juntos para prevenir la contaminación cruzada", "El mismo recipiente que los implementos usados — siempre que se enjuaguen primero", "Una bandeja abierta en el carrito de servicio donde el aire pueda circular para mantenerlos sanitarios", "La solución desinfectante en todo momento — los implementos deben permanecer sumergidos hasta su uso"], correct: 0, explanation: "After disinfecting implements, they must be stored in a clean, covered container separate from used implements. Mixing clean and used implements in the same container defeats the purpose of disinfection. Open storage (uncovered trays) allows environmental recontamination from airborne particles." },
  { id: 76, question: "Under Texas TDLR rules, all hazardous chemical products used in an esthetics establishment must be:", question_es: "Bajo las reglas de TDLR de Texas, todos los productos químicos peligrosos utilizados en un establecimiento de estética deben ser:", options: ["Kept in their original containers with the manufacturer's label intact, or properly labeled if transferred to a secondary container, and stored according to the safety requirements on the SDS", "Transferred into unlabeled spray bottles for ease of use at the service station", "Mixed with water immediately upon purchase to reduce concentration and eliminate the labeling requirement", "Kept in a locked cabinet accessible only to the establishment owner — not available to individual estheticians during services"], options_es: ["Mantenidos en sus recipientes originales con la etiqueta del fabricante intacta, o correctamente etiquetados si se transfieren a un recipiente secundario, y almacenados según los requisitos de seguridad de la SDS", "Transferidos a botellas de spray sin etiqueta para facilidad de uso en la estación de servicio", "Mezclados con agua inmediatamente al comprarlos para reducir la concentración y eliminar el requisito de etiquetado", "Mantenidos en un gabinete cerrado accesible solo al propietario del establecimiento — no disponibles para los esteticistas individuales durante los servicios"], correct: 0, explanation: "OSHA's Hazard Communication Standard and EPA regulations require that chemical products be kept in properly labeled containers. If transferred from the original container, the secondary container must be labeled with the product name, hazard warnings, and other required information. Unlabeled containers are a serious safety and regulatory violation." },
  { id: 77, question: "Texas provides license benefits for military service members and veterans seeking esthetics licensure by:", question_es: "Texas ofrece beneficios de licencia para miembros del servicio militar y veteranos que buscan licencias de estética:", options: ["Allowing military service members and veterans to receive expedited license processing and credit for relevant military training and experience toward licensing requirements under Texas Occupations Code provisions for military personnel", "Exempting all veterans from any examination requirements for the esthetics license", "Providing free tuition at Texas esthetics schools for all active duty service members only", "Giving veterans an automatic Texas esthetics license based solely on honorable discharge status"], options_es: ["Permitir a los miembros del servicio militar y veteranos recibir procesamiento expedito de licencias y crédito por capacitación y experiencia militar relevante hacia los requisitos de licencia bajo las disposiciones del Código de Ocupaciones de Texas para personal militar", "Eximir a todos los veteranos de cualquier requisito de examen para la licencia de estética", "Proporcionar matrícula gratuita en las escuelas de estética de Texas solo para todos los miembros del servicio activo", "Dar a los veteranos una licencia automática de estética de Texas basada únicamente en el estado de baja honorable"], correct: 0, explanation: "Texas Occupations Code provides benefits for military members and veterans including: expedited license processing, credit for relevant military training toward civilian licensing requirements, and temporary practice permits for spouses of deployed service members. These provisions help service members transition to civilian careers." },
  { id: 78, question: "The primary purpose of TDLR sanitation rules for Texas esthetics establishments is:", question_es: "El propósito principal de las reglas de saneamiento de TDLR para los establecimientos de estética de Texas es:", options: ["To protect clients from the transmission of infectious diseases and the spread of pathogens through improperly sanitized implements, contaminated products, and unsanitary facility conditions during esthetics services", "To create revenue through fines for establishments that fail sanitation inspections", "To ensure esthetics establishments have a pleasant aesthetic appearance for client satisfaction", "To standardize the appearance of implements and service areas across all Texas esthetics establishments"], options_es: ["Proteger a los clientes de la transmisión de enfermedades infecciosas y la propagación de patógenos a través de implementos no saneados adecuadamente, productos contaminados y condiciones de instalaciones insalubres durante los servicios de estética", "Crear ingresos a través de multas para los establecimientos que no pasan las inspecciones de saneamiento", "Garantizar que los establecimientos de estética tengan una apariencia estética agradable para la satisfacción del cliente", "Estandarizar la apariencia de los implementos y las áreas de servicio en todos los establecimientos de estética de Texas"], correct: 0, explanation: "Sanitation rules exist to protect public health — specifically to prevent the spread of infectious disease between clients and from estheticians to clients. Esthetics services create pathogen transmission opportunities through skin contact, shared implements, and product contamination. Rules are protective, not punitive in purpose." },
  { id: 79, question: "A Texas esthetics establishment that fails a TDLR sanitation inspection has the right to:", question_es: "Un establecimiento de estética de Texas que no pasa una inspección de saneamiento de TDLR tiene derecho a:", options: ["Receive written notice specifying the violations found, correct the identified deficiencies within the time frame provided, request a re-inspection to verify corrections, and appeal any adverse action through TDLR's administrative process", "Immediately close and forfeit the establishment license without any right to appeal", "Continue operating normally while the violations are under review — operations are never interrupted by a failed inspection", "Only appeal violations to the local city government, not to TDLR"], options_es: ["Recibir aviso escrito especificando las violaciones encontradas, corregir las deficiencias identificadas dentro del plazo proporcionado, solicitar una reinspección para verificar las correcciones y apelar cualquier acción adversa a través del proceso administrativo de TDLR", "Cerrar inmediatamente y perder la licencia del establecimiento sin derecho a apelar", "Continuar operando normalmente mientras las violaciones están bajo revisión — las operaciones nunca se interrumpen por una inspección fallida", "Solo apelar las violaciones al gobierno de la ciudad local, no a TDLR"], correct: 0, explanation: "Texas law provides due process for licensed establishments facing regulatory action. Written notice of violations, a reasonable correction period, re-inspection, and the right to appeal through TDLR's administrative hearing process are all part of the enforcement system. Establishments are not immediately closed for most violations." },
]

const icQ = [
  { id: 80, question: "The three main categories of microorganisms that an esthetician encounters as potential pathogens are:", question_es: "Las tres principales categorías de microorganismos que un esteticista encuentra como posibles patógenos son:", options: ["Bacteria, viruses, and fungi — all three can cause infections transmitted during esthetics services if proper sanitation is not followed", "Only bacteria and viruses — fungi are not transmitted through esthetics services", "Bacteria and parasites only — viruses cannot survive on esthetic implements", "Allergens, toxins, and bacteria — viruses are not relevant to esthetics practice"], options_es: ["Bacterias, virus y hongos — los tres pueden causar infecciones transmitidas durante los servicios de estética si no se sigue la saneamiento adecuado", "Solo bacterias y virus — los hongos no se transmiten a través de los servicios de estética", "Solo bacterias y parásitos — los virus no pueden sobrevivir en los implementos de estética", "Alérgenos, toxinas y bacterias — los virus no son relevantes para la práctica de estética"], correct: 0, explanation: "Estheticians must understand bacteria (skin infections like impetigo, folliculitis), viruses (herpes simplex, warts), and fungi (tinea, candidiasis, onychomycosis in nail services) as potential pathogens encountered in esthetics practice. Proper disinfection protocols protect against all three categories." },
  { id: 81, question: "Bacteria are classified by shape into which three categories?", question_es: "Las bacterias se clasifican por forma en cuáles tres categorías?", options: ["Cocci (spherical/round), bacilli (rod-shaped), and spirilla (spiral/corkscrew-shaped)", "Aerobic, anaerobic, and facultative — based on their oxygen requirement", "Gram-positive, gram-negative, and gram-variable — based on cell wall structure", "Pathogenic, non-pathogenic, and commensal — based on their effect on humans"], options_es: ["Cocos (esféricos/redondos), bacilos (en forma de bastón) y espirilos (en forma espiral/sacacorchos)", "Aeróbicos, anaeróbicos y facultativos — basados en su requerimiento de oxígeno", "Gram-positivos, gram-negativos y gram-variables — basados en la estructura de la pared celular", "Patógenos, no patógenos y comensales — basados en su efecto en los seres humanos"], correct: 0, explanation: "Bacterial morphology (shape) classification: cocci (round, e.g., Staphylococcus, Streptococcus), bacilli (rod-shaped, e.g., Pseudomonas), and spirilla (spiral, e.g., Treponema). This classification is foundational to microbiology and helps identify bacteria types associated with skin infections relevant to esthetics." },
  { id: 82, question: "Viruses differ from bacteria in that viruses:", question_es: "Los virus difieren de las bacterias en que los virus:", options: ["Are much smaller than bacteria, cannot reproduce outside a living host cell (they require a host to replicate), and are not affected by antibiotics", "Are larger than bacteria and can survive indefinitely on dry surfaces", "Can be killed by the same disinfectants used against bacteria", "Reproduce by binary fission just like bacteria"], options_es: ["Son mucho más pequeños que las bacterias, no pueden reproducirse fuera de una célula huésped viva (requieren un huésped para replicarse) y no son afectados por los antibióticos", "Son más grandes que las bacterias y pueden sobrevivir indefinidamente en superficies secas", "Pueden eliminarse con los mismos desinfectantes utilizados contra las bacterias", "Se reproducen por fisión binaria al igual que las bacterias"], correct: 0, explanation: "Viruses are much smaller than bacteria (submicroscopic), require a living host cell to replicate, and are not destroyed by antibiotics. However, many viruses are susceptible to appropriate EPA-registered disinfectants. Viral pathogens relevant to esthetics include herpes simplex (cold sores), wart viruses (HPV), and HIV (bloodborne)." },
  { id: 83, question: "The three levels of decontamination relevant to esthetics practice are, from least to most effective:", question_es: "Los tres niveles de descontaminación relevantes para la práctica de estética son, de menor a mayor efectividad:", options: ["Sanitization (reduces microbial count), disinfection (kills most pathogens on surfaces), and sterilization (destroys all forms of microbial life including spores)", "Cleaning, disinfecting, and sanitizing — in that order", "Rinsing, soaking, and drying", "Spraying, wiping, and ultraviolet exposure"], options_es: ["Saneamiento (reduce el recuento microbiano), desinfección (mata la mayoría de los patógenos en las superficies) y esterilización (destruye todas las formas de vida microbiana incluidas las esporas)", "Limpieza, desinfección y saneamiento — en ese orden", "Enjuague, remojo y secado", "Rociado, limpieza y exposición ultravioleta"], correct: 0, explanation: "The three decontamination levels: (1) Sanitization — reduces microbial numbers to safe levels (hand washing, cleaning surfaces). (2) Disinfection — kills most pathogens on non-living surfaces but not all spores. (3) Sterilization — destroys all microbial life including spores. Esthetics implements require disinfection; sterilization is required for items penetrating skin (needles, lancets)." },
  { id: 84, question: "In an esthetics establishment, implements must be cleaned BEFORE disinfection because:", question_es: "En un establecimiento de estética, los implementos deben limpiarse ANTES de la desinfección porque:", options: ["Organic matter (skin cells, oils, product residue, blood) on an implement inactivates many disinfectants by chemically neutralizing them or forming a physical barrier that prevents the disinfectant from contacting the microbial surface", "Cleaning after disinfection is the correct order — disinfection should always come first", "Cleaning is optional if the implement is soaked for an extended time in disinfectant", "Pre-cleaning is only required for implements that contact blood — non-blood-contact implements can be disinfected without prior cleaning"], options_es: ["La materia orgánica (células de la piel, aceites, residuos de productos, sangre) en un implemento inactiva muchos desinfectantes neutralizándolos químicamente o formando una barrera física que impide que el desinfectante entre en contacto con la superficie microbiana", "Limpiar después de la desinfección es el orden correcto — la desinfección siempre debe ir primero", "La limpieza es opcional si el implemento se sumerge durante un tiempo prolongado en desinfectante", "La prelimpieza solo se requiere para los implementos que entran en contacto con sangre — los implementos sin contacto con sangre pueden desinfectarse sin limpieza previa"], correct: 0, explanation: "The correct sequence is ALWAYS: clean first (remove visible debris with soap and water or enzymatic cleaner), then disinfect. Organic matter (blood, oils, product residue) physically blocks disinfectants from reaching pathogens and chemically inactivates some disinfectant compounds. Skipping cleaning makes disinfection ineffective." },
  { id: 85, question: "Quaternary ammonium compounds ('quats') used in esthetics establishments:", question_es: "Los compuestos de amonio cuaternario ('cuats') utilizados en los establecimientos de estética:", options: ["Are EPA-registered disinfectants effective against bacteria, some viruses, and fungi — commonly used for implement and surface disinfection; must be prepared at the correct concentration and changed per manufacturer guidelines", "Sterilize implements completely, eliminating all spores and pathogens", "Are effective only against gram-positive bacteria and have no activity against viruses", "Should be mixed at any concentration the esthetician prefers — concentration does not affect efficacy"], options_es: ["Son desinfectantes registrados por la EPA efectivos contra bacterias, algunos virus y hongos — comúnmente utilizados para la desinfección de implementos y superficies; deben prepararse a la concentración correcta y cambiarse según las pautas del fabricante", "Esterilizan completamente los implementos, eliminando todas las esporas y patógenos", "Son efectivos solo contra bacterias gram-positivas y no tienen actividad contra virus", "Deben mezclarse a la concentración que el esteticista prefiera — la concentración no afecta la eficacia"], correct: 0, explanation: "Quaternary ammonium compounds ('quats') are widely used in esthetics for surface and implement disinfection. They are EPA-registered and effective against many common pathogens. Key points: use at the correct concentration (too dilute = ineffective, too concentrated = unnecessary exposure), change the solution per manufacturer guidelines (quats can accumulate organic matter and lose effectiveness)." },
  { id: 86, question: "The chain of infection requires which six components to complete the cycle of transmission?", question_es: "La cadena de infección requiere cuáles seis componentes para completar el ciclo de transmisión?", options: ["Infectious agent, reservoir (host), portal of exit, mode of transmission, portal of entry, susceptible host — breaking any link in this chain prevents transmission", "Pathogen, moisture, oxygen, warmth, nutrition, and time — these are the six requirements for bacterial growth", "Source, contact, infection, incubation, symptoms, recovery — the six stages of infection", "Bacteria, virus, fungi, parasite, vector, and allergen — the six types of pathogens"], options_es: ["Agente infeccioso, reservorio (huésped), portal de salida, modo de transmisión, portal de entrada, huésped susceptible — romper cualquier eslabón en esta cadena previene la transmisión", "Patógeno, humedad, oxígeno, calor, nutrición y tiempo — estos son los seis requisitos para el crecimiento bacteriano", "Fuente, contacto, infección, incubación, síntomas, recuperación — las seis etapas de la infección", "Bacteria, virus, hongos, parásito, vector y alérgeno — los seis tipos de patógenos"], correct: 0, explanation: "The chain of infection model has six links: (1) Infectious agent, (2) Reservoir/host, (3) Portal of exit (how it leaves the reservoir), (4) Mode of transmission (contact, droplet, airborne, vector, vehicle), (5) Portal of entry (how it enters a new host), (6) Susceptible host. Sanitation breaks the chain at links 3, 4, and 5." },
  { id: 87, question: "Standard (universal) precautions in esthetics practice means:", question_es: "Las precauciones estándar (universales) en la práctica de estética significan:", options: ["Treating every client as if they could potentially be infectious — using appropriate PPE (gloves, masks when indicated), proper hand hygiene, and safe sharps handling for all clients regardless of known health status", "Only using protective measures for clients who disclose an infectious disease during the intake process", "Universal precautions only apply when blood is present — routine facial services require no protective measures", "Asking every client to provide a physician's health clearance letter before receiving services"], options_es: ["Tratar a cada cliente como si pudiera ser potencialmente infeccioso — usando EPP apropiado (guantes, máscaras cuando se indica), higiene de manos adecuada y manejo seguro de objetos cortantes para todos los clientes independientemente del estado de salud conocido", "Solo usar medidas protectoras para los clientes que divulgan una enfermedad infecciosa durante el proceso de admisión", "Las precauciones universales solo se aplican cuando hay sangre presente — los servicios faciales de rutina no requieren medidas protectoras", "Pedir a cada cliente que proporcione una carta de autorización médica de un médico antes de recibir servicios"], correct: 0, explanation: "Standard precautions (formerly 'universal precautions') assume that all blood and certain body fluids may be infectious regardless of the client's disclosed health status. In esthetics, this means using gloves during any service that may involve exposure to blood or non-intact skin, proper hand washing, and treating all sharps (lancets, needles) as potentially infectious." },
  { id: 88, question: "Personal Protective Equipment (PPE) used by estheticians during services may include:", question_es: "El Equipo de Protección Personal (EPP) utilizado por los esteticistas durante los servicios puede incluir:", options: ["Gloves (for services with blood or body fluid exposure risk), masks (during chemical peel application or when client is coughing/sneezing), and protective eyewear (when there is splash risk from chemicals)", "Only latex gloves — no other PPE is relevant to esthetics practice", "PPE is only required in medical spas, not in traditional esthetics establishments", "Full surgical gowns and N95 respirators for every esthetics service performed"], options_es: ["Guantes (para servicios con riesgo de exposición a sangre o fluidos corporales), máscaras (durante la aplicación de peel químico o cuando el cliente tose/estornuda) y gafas protectoras (cuando hay riesgo de salpicaduras de químicos)", "Solo guantes de látex — ningún otro EPP es relevante para la práctica de estética", "El EPP solo se requiere en spas médicos, no en establecimientos de estética tradicionales", "Batas quirúrgicas completas y respiradores N95 para cada servicio de estética realizado"], correct: 0, explanation: "PPE selection in esthetics depends on the service and associated risk. Gloves for blood/body fluid potential, masks during chemical application or respiratory exposure, eyewear for chemical splashes. PPE requirements are guided by OSHA's standards and the specific hazard assessment for each service type." },
  { id: 89, question: "If accidental blood contact occurs during an esthetics service (e.g., a skin tear during extraction), the esthetician should:", question_es: "Si ocurre contacto accidental con sangre durante un servicio de estética (por ejemplo, un desgarro de piel durante una extracción), el esteticista debe:", options: ["Stop the service, apply gloves if not already wearing them, contain the blood with absorbent material, discard contaminated single-use items, properly clean and disinfect all reusable implements and surfaces, and wash hands thoroughly", "Continue the service and disinfect the implements at the end of the session only", "Simply wipe the area with a tissue and proceed — small amounts of blood require no special protocol", "Ask the client to wait while the esthetician seeks medical attention — blood contact always constitutes a medical emergency"], options_es: ["Detener el servicio, ponerse guantes si no los lleva ya puestos, contener la sangre con material absorbente, descartar los artículos de uso único contaminados, limpiar y desinfectar adecuadamente todos los implementos reutilizables y superficies, y lavarse las manos a fondo", "Continuar el servicio y desinfectar los implementos solo al final de la sesión", "Simplemente limpiar el área con un pañuelo de papel y continuar — pequeñas cantidades de sangre no requieren ningún protocolo especial", "Pedir al cliente que espere mientras el esteticista busca atención médica — el contacto con sangre siempre constituye una emergencia médica"], correct: 0, explanation: "Blood contact requires immediate response: glove up, contain the blood, properly dispose of contaminated single-use items, clean and disinfect all surfaces and reusable implements that may have been contaminated, and wash hands. This protocol is part of OSHA's Bloodborne Pathogen Standard requirements." },
  { id: 90, question: "Sterilization in an esthetics establishment is required for:", question_es: "La esterilización en un establecimiento de estética se requiere para:", options: ["Any implement that penetrates the skin (such as lancets, microneedling needles, and other invasive devices) — these items must be sterile before use because they breach the skin's protective barrier", "All facial brushes, sponges, and applicators used in non-invasive facial services", "All implements used in an esthetics establishment as a replacement for disinfection", "Implements used only on clients with known immune system conditions"], options_es: ["Cualquier implemento que penetra la piel (como lancetas, agujas de microagujas y otros dispositivos invasivos) — estos artículos deben ser estériles antes de su uso porque rompen la barrera protectora de la piel", "Todos los cepillos faciales, esponjas y aplicadores utilizados en servicios faciales no invasivos", "Todos los implementos utilizados en un establecimiento de estética como reemplazo de la desinfección", "Implementos utilizados solo en clientes con condiciones conocidas del sistema inmunológico"], correct: 0, explanation: "Sterilization (destruction of all microbial life including spores) is required for any item that penetrates intact skin. In esthetics, this means lancets, needles, and any invasive device. Most esthetics implements (tweezers, spatulas, extractors) require disinfection — not sterilization — because they contact intact skin only." },
  { id: 91, question: "An autoclave sterilizes implements by:", question_es: "Un autoclave esteriliza los implementos mediante:", options: ["Using pressurized steam at high temperature (typically 121°C/250°F at 15 psi) for a specified time — the combination of heat, steam, and pressure destroys all microbial life including bacterial endospores", "Using ultraviolet light to destroy microbial DNA on the implement surface", "Submerging implements in a chemical sterilization solution for 24 hours", "Heating implements in a dry oven at 350°F until all moisture is removed"], options_es: ["Usando vapor a presión a alta temperatura (típicamente 121°C/250°F a 15 psi) durante un tiempo especificado — la combinación de calor, vapor y presión destruye toda la vida microbiana incluidas las endosporas bacterianas", "Usando luz ultravioleta para destruir el ADN microbiano en la superficie del implemento", "Sumergiendo los implementos en una solución de esterilización química durante 24 horas", "Calentando los implementos en un horno seco a 350°F hasta que se elimine toda la humedad"], correct: 0, explanation: "Autoclaves use pressurized steam (moist heat) at 121°C and 15 psi for 15–30 minutes to achieve sterilization. This combination of temperature, steam, and pressure denatures proteins and destroys all microbial life including the most resistant bacterial endospores. Autoclaves are used for skin-piercing implements." },
  { id: 92, question: "An ultraviolet (UV) sanitizing cabinet in an esthetics establishment:", question_es: "Un gabinete de saneamiento ultravioleta (UV) en un establecimiento de estética:", options: ["Is used for STORAGE of cleaned and disinfected implements — UV maintains cleanliness of already-disinfected tools but is NOT a substitute for proper disinfection or sterilization of implements", "Sterilizes implements, replacing the need for an autoclave or chemical disinfection", "Disinfects implements to the same level as EPA-registered disinfectants", "Is required by TDLR in all Texas esthetics establishments as the primary sanitation method"], options_es: ["Se usa para ALMACENAR implementos limpios y desinfectados — el UV mantiene la limpieza de las herramientas ya desinfectadas pero NO es sustituto de la desinfección o esterilización adecuada de los implementos", "Esteriliza los implementos, reemplazando la necesidad de un autoclave o desinfección química", "Desinfecta los implementos al mismo nivel que los desinfectantes registrados por la EPA", "Es requerido por TDLR en todos los establecimientos de estética de Texas como método primario de saneamiento"], correct: 0, explanation: "UV cabinets are commonly misunderstood. UV light only contacts the exposed surface of implements and is not reliable for disinfection or sterilization. UV cabinets are best used for STORING already-disinfected implements to prevent recontamination. They are NOT a substitute for cleaning and proper chemical disinfection." },
  { id: 93, question: "Contaminated implements in an esthetics establishment must be:", question_es: "Los implementos contaminados en un establecimiento de estética deben ser:", options: ["Immediately removed from the service area, placed in a labeled container for contaminated items, cleaned, and then properly disinfected before any reuse — never left on the service area uncovered", "Left on the service tray and disinfected between clients only at the end of each hour", "Rinsed with warm water immediately and placed back on the service tray", "Discarded after every use — no reusable implements are permitted in Texas esthetics"], options_es: ["Inmediatamente retirados del área de servicio, colocados en un recipiente etiquetado para artículos contaminados, limpiados y luego correctamente desinfectados antes de cualquier reutilización — nunca dejados en el área de servicio sin cubrir", "Dejados en la bandeja de servicio y desinfectados entre clientes solo al final de cada hora", "Enjuagados con agua tibia de inmediato y colocados de nuevo en la bandeja de servicio", "Desechados después de cada uso — no se permiten implementos reutilizables en la estética de Texas"], correct: 0, explanation: "After each client, contaminated implements must be immediately removed from the service area, placed in a clearly marked container for contaminated/dirty items (separate from clean items), then properly cleaned and disinfected. Leaving used implements on the service surface risks cross-contamination if a new client or another esthetician contacts them." },
  { id: 94, question: "The most effective method of preventing disease transmission in an esthetics establishment is:", question_es: "El método más efectivo para prevenir la transmisión de enfermedades en un establecimiento de estética es:", options: ["Consistent, correct hand washing by the esthetician before and after each client service — hand hygiene is the single most important infection control measure", "Wearing gloves for all services, regardless of whether skin contact is expected", "Using only disposable implements so that disinfection is never required", "Requiring clients to wash their hands before entering the service room"], options_es: ["El lavado de manos consistente y correcto por parte del esteticista antes y después de cada servicio al cliente — la higiene de manos es la medida de control de infecciones más importante", "Usar guantes para todos los servicios, independientemente de si se espera contacto con la piel", "Usar solo implementos desechables para que nunca se requiera desinfección", "Requerir que los clientes se laven las manos antes de entrar a la sala de servicio"], correct: 0, explanation: "Consistent hand washing (or hand hygiene) before and after each client is the single most effective way to prevent disease transmission in healthcare and personal care settings. The esthetician's hands are the primary vector for transferring pathogens between clients, themselves, and surfaces." },
  { id: 95, question: "Tinea versicolor, tinea faciei, and tinea corporis are all caused by:", question_es: "La tiña versicolor, la tiña facial y la tiña corporal son causadas por:", options: ["Fungi — specifically dermatophytes (or in the case of tinea versicolor, Malassezia yeast) that infect the superficial layers of the skin", "Bacteria — specifically Staphylococcus aureus", "Viruses — specifically the herpes simplex virus type 1", "Parasites — specifically Sarcoptes scabiei mites"], options_es: ["Hongos — específicamente dermatofitos (o en el caso de la tiña versicolor, la levadura Malassezia) que infectan las capas superficiales de la piel", "Bacterias — específicamente Staphylococcus aureus", "Virus — específicamente el virus herpes simplex tipo 1", "Parásitos — específicamente los ácaros Sarcoptes scabiei"], correct: 0, explanation: "Tinea infections are fungal skin infections caused by dermatophytes (except tinea versicolor, caused by Malassezia yeast). Tinea faciei affects the face; tinea corporis (ringworm) affects the body. These infections are contagious and are contraindications for esthetics services in the affected area — the esthetician must refer the client to a physician." },
  { id: 96, question: "Herpes simplex virus type 1 (HSV-1), which causes oral cold sores, is relevant to esthetics because:", question_es: "El virus herpes simplex tipo 1 (HSV-1), que causa úlceras bucales orales, es relevante para la estética porque:", options: ["An active HSV-1 outbreak on the face is a contraindication for facial services — performing extractions, waxing, or applying heat near active lesions can spread the virus and cause a more severe outbreak", "HSV-1 is not contagious through skin contact — esthetics services are safe during an active outbreak", "HSV-1 only affects the lips and is not a concern for the esthetician as long as facial services avoid the mouth area", "The HSV-1 virus is completely eliminated by standard disinfectants — implement disinfection removes all risk"], options_es: ["Un brote activo de HSV-1 en el rostro es una contraindicación para los servicios faciales — realizar extracciones, encerado o aplicar calor cerca de lesiones activas puede diseminar el virus y causar un brote más severo", "El HSV-1 no es contagioso a través del contacto con la piel — los servicios de estética son seguros durante un brote activo", "El HSV-1 solo afecta los labios y no es una preocupación para el esteticista siempre que los servicios faciales eviten el área de la boca", "El virus HSV-1 es completamente eliminado por los desinfectantes estándar — la desinfección de implementos elimina todo riesgo"], correct: 0, explanation: "HSV-1 is highly contagious during active outbreaks. Services involving heat, manipulation, or trauma near active lesions can spread the virus to other parts of the face or to other clients via implements. Active herpes lesions are a service contraindication. Implements that contacted active lesions must be properly disinfected." },
  { id: 97, question: "Methicillin-resistant Staphylococcus aureus (MRSA) is relevant to esthetics practice because:", question_es: "El Staphylococcus aureus resistente a la meticilina (MRSA) es relevante para la práctica de estética porque:", options: ["MRSA is an antibiotic-resistant bacterium that can survive on surfaces and implements — infections can result from improper sanitation during facial services involving extractions or skin manipulation that creates micro-abrasions", "MRSA only affects hospitalized patients and has no relevance to esthetics establishments", "MRSA is killed by soap and water alone — disinfection is unnecessary for MRSA prevention in esthetics", "MRSA infections require direct blood contact — routine facial services present no MRSA risk"], options_es: ["MRSA es una bacteria resistente a los antibióticos que puede sobrevivir en superficies e implementos — las infecciones pueden resultar de un saneamiento inadecuado durante los servicios faciales que involucran extracciones o manipulación de la piel que crea micro-abrasiones", "MRSA solo afecta a los pacientes hospitalizados y no tiene relevancia para los establecimientos de estética", "MRSA se elimina solo con jabón y agua — la desinfección es innecesaria para la prevención de MRSA en la estética", "Las infecciones de MRSA requieren contacto directo con la sangre — los servicios faciales de rutina no presentan riesgo de MRSA"], correct: 0, explanation: "MRSA can survive on dry surfaces for hours and can colonize skin. Extractions, waxing, and microneedling create micro-abrasions that can be entry points for MRSA. EPA-registered hospital-level disinfectants labeled for MRSA kill this bacterium on surfaces and implements. Proper sanitation is essential for MRSA prevention." },
  { id: 98, question: "Scabies is relevant to esthetics practice because:", question_es: "La sarna es relevante para la práctica de estética porque:", options: ["Scabies (caused by the mite Sarcoptes scabiei) is highly contagious through prolonged skin contact and can be transmitted during facial and body esthetics services — active scabies is a contraindication for service", "Scabies only affects the feet and hands — facial esthetics services present no scabies risk", "Scabies is transmitted only through sexual contact and is not relevant to esthetics practice", "Scabies is killed by standard salon disinfectants before any transmission can occur during a service"], options_es: ["La sarna (causada por el ácaro Sarcoptes scabiei) es muy contagiosa a través del contacto cutáneo prolongado y puede transmitirse durante los servicios de estética facial y corporal — la sarna activa es una contraindicación para el servicio", "La sarna solo afecta los pies y las manos — los servicios de estética facial no presentan riesgo de sarna", "La sarna solo se transmite a través del contacto sexual y no es relevante para la práctica de estética", "La sarna es eliminada por los desinfectantes estándar del salón antes de que pueda ocurrir cualquier transmisión durante un servicio"], correct: 0, explanation: "Scabies mites burrow into the skin and are highly contagious through prolonged skin contact. An esthetics session — involving extended close skin contact — is a potential transmission event if the client has active scabies. Scabies is a contraindication; the client must be referred to a physician for diagnosis and treatment." },
  { id: 99, question: "Properly disinfected implements in an esthetics establishment must be stored:", question_es: "Los implementos correctamente desinfectados en un establecimiento de estética deben almacenarse:", options: ["In a clean, closed container, drawer, or cabinet separate from used/contaminated implements — to prevent recontamination before use on the next client", "In the disinfectant solution until the next client arrives — soaking them maintains their disinfected state", "On an open surface so air can keep them dry — moisture is the only recontamination risk", "In the same container as new, unopened implements to save space"], options_es: ["En un recipiente limpio y cerrado, cajón o gabinete separado de los implementos usados/contaminados — para prevenir la recontaminación antes de su uso en el próximo cliente", "En la solución desinfectante hasta que llegue el próximo cliente — mantenerlos en remojo mantiene su estado desinfectado", "En una superficie abierta para que el aire los mantenga secos — la humedad es el único riesgo de recontaminación", "En el mismo recipiente que los implementos nuevos y sin abrir para ahorrar espacio"], correct: 0, explanation: "After disinfection and drying, implements must be stored in a clean, closed container to prevent recontamination from the environment (airborne particles, dust, contact). They must be kept separate from contaminated items. Leaving disinfected implements in solution too long can cause product degradation and recontamination if the solution has not been properly changed." },
  { id: 100, question: "An esthetics establishment that uses lancets or other skin-piercing implements must:", question_es: "Un establecimiento de estética que usa lancetas u otros implementos que perforan la piel debe:", options: ["Use only sterile, single-use disposable lancets or needles — these are never reused between clients; used sharps must be disposed of in an approved sharps container following OSHA bloodborne pathogen guidelines", "Sterilize lancets in the autoclave between clients for reuse to reduce costs", "Use lancets only after disinfecting them in 70% isopropyl alcohol for 2 minutes — no autoclave is required", "Only use lancets that are purchased in bulk and stored in a disinfectant solution"], options_es: ["Usar solo lancetas o agujas desechables de uso único y estériles — nunca se reutilizan entre clientes; los objetos cortantes usados deben desecharse en un recipiente de objetos cortantes aprobado siguiendo las pautas de patógenos de transmisión sanguínea de OSHA", "Esterilizar las lancetas en el autoclave entre clientes para reutilizarlas y reducir costos", "Usar lancetas solo después de desinfectarlas en alcohol isopropílico al 70% durante 2 minutos — no se requiere autoclave", "Solo usar lancetas que se compran a granel y se almacenan en una solución desinfectante"], correct: 0, explanation: "Lancets and needles used in esthetics (for extractions, lancing milia, microneedling) must be sterile and single-use. They are NEVER reused between clients. Used sharps must be placed immediately into an approved sharps disposal container (puncture-resistant). Sharps containers must be disposed of properly according to local regulations." },
]

let out = readFileSync(FILE, 'utf8')
out += tdQ.map(q => fmt(q, tdT, tdTes, tdPt, tdPtes)).join('\n') + '\n'
out += '\n// ─── INFECTION CONTROL & SANITATION (ids 80–184) ────────────────────────────\n'
out += icQ.map(q => fmt(q, icT, icTes, icPt, icPtes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${tdQ.length} TDLR (ids ${tdQ[0].id}–${tdQ[tdQ.length-1].id}) + ${icQ.length} Infection Control (ids ${icQ[0].id}–${icQ[icQ.length-1].id})`)
